const uint row = threadgroup_position_in_grid.x;
const uint tid = thread_position_in_threadgroup.x;
const uint lane = thread_index_in_simdgroup;
const uint sg = simdgroup_index_in_threadgroup;
const uint base = row * H;
threadgroup float part[8];

float ss = 0.0f;
if (H % 4 == 0) {
    const uint V = H / 4;
    for (uint i = tid; i < V; i += 256) {
        half4 hv = half4(ld4(x, base + i * 4) + ld4(r, base + i * 4));
        st4(h, base + i * 4, hv);
        float4 f = float4(hv);
        ss += dot(f, f);
    }
} else {
    for (uint i = tid; i < H; i += 256) {
        half hv = half(float(x[base + i]) + float(r[base + i]));
        h[base + i] = hv;
        float f = float(hv);
        ss += f * f;
    }
}
ss = simd_sum(ss);
if (lane == 0) part[sg] = ss;
threadgroup_barrier(mem_flags::mem_threadgroup);
float tot = 0.0f;
for (uint k = 0; k < 8; k++) tot += part[k];
const float inv = rsqrt(tot / float(H) + 1e-5f);

if (H % 4 == 0) {
    const uint V = H / 4;
    for (uint i = tid; i < V; i += 256) {
        float4 f = float4(ld4(h, base + i * 4));
        float4 wv = float4(ld4(w, i * 4));
        st4(y, base + i * 4, half4(f * inv * wv));
    }
} else {
    for (uint i = tid; i < H; i += 256) {
        y[base + i] = half(float(h[base + i]) * inv * float(w[i]));
    }
}

